import fs from 'node:fs';
import zlib from 'node:zlib';
const buf = fs.readFileSync('site/fonts/acme-sans.woff2');
const tags = ['cmap','head','hhea','hmtx','maxp','name','OS/2','post','cvt ','fpgm','glyf','loca','prep','CFF ','VORG','EBDT','EBLC','gasp','hdmx','kern','LTSH','PCLT','VDMX','vhea','vmtx','BASE','GDEF','GPOS','GSUB','EBSC','JSTF','MATH','CBDT','CBLC','COLR','CPAL','SVG ','sbix','acnt','avar','bdat','bloc','bsln','cvar','fdsc','feat','fmtx','fvar','gvar','hsty','just','lcar','mort','morx','opbd','prop','trak','Zapf','Silf','Glat','Gloc','Feat','Sill'];
const numTables = buf.readUInt16BE(12);
const totalCompressed = buf.readUInt32BE(20);
let off = 48; const dir = [];
function u128() { let v=0; for(let i=0;i<5;i++){ const b=buf[off++]; v=(v<<7)|(b&0x7f); if(!(b&0x80)) return v; } throw new Error('bad u128'); }
for (let i=0;i<numTables;i++){
  const flags = buf[off++];
  const idx = flags & 0x3f; const tv = (flags >> 6) & 0x3;
  let tag = idx===63 ? buf.toString('latin1', off, (off+=4)) : tags[idx];
  const origLength = u128();
  const transformed = !((tag==='glyf'||tag==='loca') && tv===0);
  const transformLength = transformed ? u128() : origLength;
  dir.push({tag, origLength, transformLength, tv});
}
console.log('dir end offset', off, 'compressed len', totalCompressed, 'file len', buf.length);
console.log(dir.map(d=>d.tag+':'+d.origLength).join(' '));
const comp = buf.subarray(off, off+totalCompressed);
const raw = zlib.brotliDecompressSync(comp);
console.log('decompressed bytes', raw.length);
let p = 0;
for (const d of dir) {
  const data = raw.subarray(p, p+d.transformLength);
  if (d.tag === 'fvar') {
    const version = data.readUInt32BE(0);
    const axesOff = data.readUInt16BE(4);
    const countSizePairs = data.readUInt16BE(6);
